public async Task ProcessAsync(Message message, CancellationToken ct)
{
    using var tx = await _db.BeginTransactionAsync(ct);

    // Check if already processed
    var exists = await _db.ProcessedMessages
        .AnyAsync(p => p.MessageId == message.Id, ct);

    if (exists)
    {
        await tx.CommitAsync(ct);
        return; // Already done
    }

    // Process the business logic
    await _orderService.ConfirmOrderAsync(message.OrderId, ct);

    // Mark as processed
    await _db.ProcessedMessages.AddAsync(new ProcessedMessage
    {
        MessageId = message.Id,
        ProcessedAt = DateTime.UtcNow
    }, ct);

    await tx.CommitAsync(ct);
}
